-- Schema/constraints/RLS modeled from the audited central contract; synthetic data only.
create role anon; create role authenticated; create role service_role bypassrls;
create schema auth; create schema delivery_private;
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
grant usage on schema auth,public to anon,authenticated,service_role;
create table public.managed_sites(id uuid primary key,nx_id text,name text,status text,plan_code text,billing_active boolean default true,plan_started_at timestamptz default now(),plan_expires_at timestamptz,payment_status text);
create table public.store_members(store_id uuid references managed_sites,user_id uuid,role text,is_active boolean,primary key(store_id,user_id));
alter table public.store_members enable row level security;
create policy own_membership on public.store_members for select to authenticated using(user_id=auth.uid());
grant select on public.store_members to authenticated;
create function public.novaesweb_connect_is_active_store_member(target_store_id uuid) returns boolean language sql stable set search_path='' as $$select exists(select 1 from public.store_members where store_id=target_store_id and user_id=auth.uid() and is_active)$$;
alter table public.managed_sites enable row level security;
create policy own_store on public.managed_sites for select to authenticated using(public.novaesweb_connect_is_active_store_member(id));
grant select on public.managed_sites to authenticated;
create type public.order_lifecycle_event_type as enum('created','accepted','rejected','delivered','cancelled','hidden','adjustment');
create type public.order_cancellation_category as enum('cliente_desistiu','endereco_fora_raio','item_esgotado','estabelecimento_lotado','erro_operacional_loja','falha_comunicacao','outros');
create function public.novaesweb_order_competence(p_ts timestamptz) returns date language sql immutable set search_path='' as $$select date_trunc('month',p_ts at time zone 'America/Sao_Paulo')::date$$;
create table public.store_order_usage_events(id uuid primary key default gen_random_uuid(),store_id uuid not null references managed_sites,order_ref text not null,accepted_at timestamptz not null,competence date not null,source text not null check(source in ('store_rpc','delivery_orders_trigger')),is_voided boolean not null default false,unique(store_id,order_ref),check(competence=public.novaesweb_order_competence(accepted_at)));
create table public.store_order_lifecycle_events(id uuid primary key default gen_random_uuid(),store_id uuid not null references managed_sites,order_ref text not null,event_type public.order_lifecycle_event_type not null,occurred_at timestamptz not null,competence text not null,source text not null check(source in ('store_rpc','delivery_orders_trigger','master_adjustment')),reason_category public.order_cancellation_category,unique(store_id,order_ref,event_type),check(competence=to_char(public.novaesweb_order_competence(occurred_at),'YYYY-MM')));
alter table public.store_order_usage_events enable row level security;
alter table public.store_order_lifecycle_events enable row level security;
create policy usage_store_member_read on public.store_order_usage_events for select to authenticated using(public.novaesweb_connect_is_active_store_member(store_id));
create policy lifecycle_store_member_read on public.store_order_lifecycle_events for select to authenticated using(public.novaesweb_connect_is_active_store_member(store_id));
grant select on public.store_order_usage_events,public.store_order_lifecycle_events to authenticated;
create table public.delivery_orders(id uuid primary key default gen_random_uuid(),store_id uuid not null references managed_sites,status text not null default 'recebido',payload jsonb default '{}',created_at timestamptz not null default now());
alter table public.delivery_orders enable row level security;
grant select,insert,update,delete on public.delivery_orders to authenticated;
create function public.delivery_has_role(target uuid,allowed_roles text[]) returns boolean language sql stable set search_path='' as $$select exists(select 1 from public.managed_sites s join public.store_members m on m.store_id=s.id where s.id=target and s.status in ('active','maintenance') and m.user_id=auth.uid() and m.is_active and m.role=any(allowed_roles))$$;
create policy own_order on public.delivery_orders to authenticated using(public.delivery_has_role(store_id,array['owner','admin','staff'])) with check(public.delivery_has_role(store_id,array['owner','admin','staff']));
create function delivery_private.prevent_store_transfer() returns trigger language plpgsql as $$begin if new.store_id is distinct from old.store_id then raise exception 'STORE_TRANSFER_FORBIDDEN';end if;return new;end$$;
create trigger prevent_store_transfer before update on public.delivery_orders for each row execute function delivery_private.prevent_store_transfer();
